{
  "assay_type": "Biochemical haspin concentration-response inhibition assay; proposed ADP-Glo format",
  "system": "Purified active haspin (Q8TF76), a validated kinase substrate and ATP; enzyme construct, substrate identity and buffer remain unresolved.",
  "readout": "Luminescence reporting ADP production after residual ATP depletion; reduced corrected signal indicates reduced kinase activity only if detection interference is excluded.",
  "steps": [
    {
      "card_id": "kinase-prepare",
      "instruction": "Prepare CHEMBL4278808 concentrations and matched controls. Before committing the definitive assay, confirm compound solubility and vehicle tolerance, and establish enzyme/substrate/ATP conditions with a linear reaction time course and an adequate signal window. This qualification is a proposed adaptation required because the packet provides no executable reaction conditions. Proceed with the proposed series only if soluble and compatible; otherwise revise its limits explicitly.",
      "parameters": {
        "top_concentration_uM": {"value": 10, "unit": "uM", "evidence": "Provisional design assumption, not a sourced compound-specific concentration; selected to extend above the retained other-compound examples, contingent on solubility and assay compatibility."},
        "dilution_factor": {"value": 3, "evidence": "Provisional design assumption balancing broad coverage with sampling density."},
        "n_points": {"value": 10, "evidence": "Provisional design assumption; ten nonzero concentrations from 10 uM to approximately 0.000508 uM, plus separate vehicle wells."},
        "replicates": {"value": 3, "evidence": "Provisional design assumption: technical triplicates per concentration and control to assess within-run scatter; these do not establish between-run reproducibility."},
        "vehicle_fraction": "Unresolved: determine a tolerated final fraction and hold it constant across concentrations and matched controls.",
        "qualification_conditions": "Enzyme construct/activity, substrate identity, buffer, pH, reaction volume, plate format, mixing and compound preincubation are unresolved; qualify and document before definitive measurement."
      }
    },
    {
      "card_id": "kinase-react",
      "instruction": "After qualification, combine compound, active haspin and validated substrate, initiate consistently with ATP, and incubate all wells under the same documented conditions. Use conditions within the qualified linear activity window without excessive substrate consumption.",
      "parameters": {
        "enzyme_concentration": "Unresolved; select by activity titration and time-course qualification.",
        "substrate_concentration": "Unresolved; select after validating the substrate and reaction window.",
        "ATP_concentration": "Unresolved; establish and report the actual concentration and its relationship to measured ATP dependence where available. Do not infer it from contextual IC50 values.",
        "reaction_time": "Unresolved; select from a qualified linear time window.",
        "temperature": "Unresolved; qualify and hold constant."
      }
    },
    {
      "card_id": "kinase-detect",
      "instruction": "Follow the supplied ADP-Glo sequence: stop the kinase reaction and deplete residual ATP, then perform ADP detection and read luminescence. Run matched background wells and fixed-ADP detection controls across compound concentrations to check whether the compound itself alters the detection signal. Obtain and validate the reagent procedure before execution.",
      "parameters": {
        "reagent_volumes": "Unresolved; no volume ratios or reaction volumes are supplied.",
        "depletion_time": "Unresolved; no supported depletion duration is supplied.",
        "detection_time": "Unresolved; no supported detection duration is supplied.",
        "read_settings": "Unresolved; qualify detector settings and signal range."
      }
    },
    {
      "card_id": "analyse",
      "instruction": "Subtract matched no-enzyme background. Normalize vehicle-treated enzyme activity to 100% and the no-enzyme background to 0%; express inhibition as 100 minus normalized activity. Inspect technical replicates and interference controls before fitting. Fit inhibition versus log concentration and report an IC50 with uncertainty only if the response brackets 50% and supports an identifiable curve. Otherwise report the observed range and repeat with a revised, qualified concentration range; do not extrapolate a potency from the retained examples.",
      "parameters": {
        "fit_model": "Provisional analysis assumption: four-parameter logistic curve with fitted slope and asymptotes when the data support them; document fitting choices and confidence interval method.",
        "acceptance_criteria": "Proposed qualitative gates: adequate vehicle/background separation, reproducible control behavior, acceptable replicate scatter, no material concentration-dependent detection interference, and sufficient curve coverage. Numerical thresholds are unresolved and must be set prospectively during qualification.",
        "confirmation": "Proposed follow-up: repeat a qualified concentration-response in independent runs to assess reproducibility; independent-run count remains unresolved."
      }
    }
  ],
  "top_concentration_uM": 10,
  "dilution_factor": 3,
  "n_points": 10,
  "replicates": 3,
  "controls": [
    "Active haspin plus substrate and ATP with matched vehicle, establishing uninhibited activity.",
    "Matched no-enzyme wells, including compound concentrations as needed, establishing nonenzymatic and reagent background.",
    "Reference haspin inhibitor concentration-response: CHEMBL1952329 is a provisional candidate because CHEMBL2184774 reports haspin inhibition; identity, availability and behavior in this format require verification. Its retained potency is not an acceptance target for this assay.",
    "Fixed-ADP detection controls with vehicle and the compound series, processed through detection without kinase turnover, to identify detection inhibition or enhancement.",
    "Vehicle-tolerance and compound-solubility checks before accepting the proposed concentration range."
  ],
  "rationale": "The question concerns biochemical inhibition, so the kinase cards followed by analysis match the system; cell-viability cards do not. ADP-Glo is supported as a candidate workflow by kinase-detect, but the retained assay descriptions do not establish that they used this format. Other-compound measurements span 34–770 nM and support considering a broad exploratory series, not predicting CHEMBL4278808 potency. The assumed ten-point, threefold series extends below and above that contextual interval, while triplicates support assessment of within-run variability. All proposed numeric settings are design assumptions pending qualification, not extracted reaction conditions.",
  "citations": ["Q8TF76", "CHEMBL4278808", "kinase-prepare", "kinase-react", "kinase-detect", "analyse", "CHEMBL2184774", "CHEMBL2176972", "CHEMBL5242305", "CHEMBL5241090", "CHEMBL3778428", "CHEMBL3774321"],
  "limitations": [
    "The packet does not support exact enzyme, substrate, ATP, buffer, temperature, timing, volume or vehicle settings; the design requires qualification before execution.",
    "The concentration range, point spacing and technical replication are explicitly provisional choices. The proposed upper concentration may fail solubility or compatibility checks, and the response may fall outside the tested range.",
    "Retained examples are other compounds, not similarity-ranked, and have sparse assay descriptions with unknown origins in several cases. Their potencies cannot be transferred to CHEMBL4278808 or used to calibrate this assay without validation.",
    "ATP concentration and other reaction conditions can affect the measured inhibition curve; report any measured IC50 as conditional on the qualified assay settings.",
    "Technical triplicates do not measure independent-run variation. Poor curve coverage or detection interference can prevent an interpretable IC50.",
    "A valid result establishes inhibition of purified haspin activity under the tested conditions. It does not establish cellular viability effects, cellular target engagement, selectivity, or a target-specific causal mechanism in cells. No potency for CHEMBL4278808 is predicted."
  ]
}
